public class VendingMachineStateTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        VendingMachineState m = new VendingMachineState(65, 2);
        check("insert(25)", "accepted", m.insert(25));
        check("insert(7) is rejected", "rejected", m.insert(7));
        check("credit after one good and one bad coin", 25, m.getCredit());
        check("dispense with 25 credit", "need 40 more", m.dispense());
        check("credit unchanged after refusal", 25, m.getCredit());
        m.insert(100);
        check("dispense with 125 credit", "dispensed with change 60", m.dispense());
        check("credit cleared by sale", 0, m.getCredit());
        check("stock after sale", 1, m.getStock());
        m.insert(100);
        m.dispense();
        check("stock after second sale", 0, m.getStock());
        m.insert(25);
        check("dispense when empty", "sold out", m.dispense());
        check("refund returns credit", 25, m.refund());
        check("credit after refund", 0, m.getCredit());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
