public class VendingMachineState {

    private final int priceCents;
    private int stock;
    private int creditCents;

    public VendingMachineState(int priceCents, int stock) {
        this.priceCents = priceCents;
        this.stock = stock;
        this.creditCents = 0;
    }

    public int getCredit() {
        return creditCents;
    }

    public int getStock() {
        return stock;
    }

    public String insert(int cents) {
        if (cents == 5 || cents == 10 || cents == 25 || cents == 100) {
            creditCents += cents;
            return "accepted";
        }
        return "rejected";
    }

    public String dispense() {
        if (stock <= 0) {
            return "sold out";
        }
        if (creditCents < priceCents) {
            return "need " + (priceCents - creditCents) + " more";
        }
        int change = creditCents - priceCents;
        stock--;
        creditCents = 0;
        return "dispensed with change " + change;
    }

    public int refund() {
        int owed = creditCents;
        creditCents = 0;
        return owed;
    }
}
